{
  "bioavailability_prediction": "high",
  "claims": [
    {
      "card_ids": ["C56"],
      "claim": "C56 reports dapagliflozin absolute oral bioavailability of 78% (90% CI 73–83%) in healthy subjects, well above the 20% threshold.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C92"],
      "claim": "C92 reports metoclopramide absolute oral bioavailability of 0.801 ± 0.049 in six subjects, well above the 20% threshold.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C73"],
      "claim": "C73 reports verapamil absolute oral bioavailability of 18.0% in healthy volunteers, below the 20% threshold.",
      "evidence_role": "contradictory"
    }
  ],
  "confidence": "high",
  "decision_summary": "Across the supplied evidence molecules, ordinary-condition absolute bioavailability values are predominantly above the 20% threshold, with many values in the 30–100% range. One molecule has mixed values straddling the threshold, but the weight of direct absolute measurements supports high oral bioavailability.",
  "evidence_gaps": [
    "Molecule 1 grouping contains an inconsistent lisurid record (C02) and an unspecified one-patient record (C23); these were discounted, leaving a provenance conflict.",
    "Molecule 5 has direct absolute bioavailability values both below (18.0%, 19.4%) and above (22–50%) the threshold, creating uncertainty around the threshold for that molecule.",
    "Some records come from special populations (infants, cirrhosis, dialysis patients) and altered formulations; these were downweighted relative to ordinary healthy-subject data."
  ],
  "new_evidence_assessment": [],
  "revision_action": "initial"
}

